{"success": true, "data": {"stdout": """"Step 4: Hybrid retrieval (BM25 + dense) for both query types."""
import os
os.environ["OPENAI_API_KEY"] = "dummy"  # pyserini imports openai unconditionally

import json
import numpy as np
import faiss
import torch
from sentence_transformers import SentenceTransformer
from pyserini.search.lucene import LuceneSearcher
from config import (QUERIES_PATH, RETRIEVAL_PATH, CORPUS_PATH,
                    BM25_INDEX_DIR, FAISS_INDEX_PATH, MODEL_BGE,
                    TOP_K, RRF_K, BATCH_SIZE_EMBED)


def reciprocal_rank_fusion(bm25_results, dense_results, k=60, top_k=5):
    """Fuse BM25 and dense results using reciprocal rank fusion."""
    scores = {}
    for rank, (doc_id, _) in enumerate(bm25_results):
        scores[doc_id] = scores.get(doc_id, 0) + 1.0 / (k + rank + 1)
    for rank, (doc_id, _) in enumerate(dense_results):
        scores[doc_id] = scores.get(doc_id, 0) + 1.0 / (k + rank + 1)
    ranked = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    return ranked[:top_k]


def run_step4(queries_data, corpus, bm25_searcher, dense_model, faiss_index,
              top_k=5, rrf_k=60, verbose=False):
    results = []
    id_to_idx = {doc["id"]: i for i, doc in enumerate(corpus)}

    for i, item in enumerate(queries_data):
        if verbose and (i+1) % 20 == 0:
            print(f"  [{i+1}/{len(queries_data)}]...")

        item_results = {
            "id": item["id"],
            "question": item["question"],
            "answer": item["answer"],
            "retrieval_pairs": []
        }

        for pair in item["query_pairs"]:
            claim = pair["claim"]
            pair_result = {"claim": claim}

            for qtype in ["answer_seeking", "verification"]:
                query = pair[qtype]

                # BM25 retrieval
                bm25_hits = bm25_searcher.search(query, k=top_k * 2)
                bm25_results = [(hit.docid, hit.score) for hit in bm25_hits]

                # Dense retrieval
                q_emb = dense_model.encode([query], normalize_embeddings=True)
                q_emb = np.array(q_emb, dtype=np.float32)
                scores, indices = faiss_index.search(q_emb, top_k * 2)
                dense_results = [(corpus[idx]["id"], float(scores[0][j]))
                                for j, idx in enumerate(indices[0]) if idx >= 0]

                # Hybrid fusion
                fused = reciprocal_rank_fusion(bm25_results, dense_results, k=rrf_k, top_k=top_k)

                retrieved = []
                for doc_id, rrf_score in fused:
                    if doc_id in id_to_idx:
                        doc = corpus[id_to_idx[doc_id]]
                        retrieved.append({
                            "doc_id": doc_id,
                            "title": doc.get("title", ""),
                            "text": doc["contents"],
                            "rrf_score": rrf_score
                        })

                pair_result[qtype] = {
                    "query": query,
                    "retrieved": retrieved
                }

            item_results["retrieval_pairs"].append(pair_result)

        results.append(item_results)

    return results


def main(limit=None, verbose=True):
    if verbose:
        print("Step 4: Hybrid Retrieval")

    if verbose:
        print(f"  Loading queries...")
    with open(QUERIES_PATH) as f:
        queries_data = json.load(f)
    if limit:
        queries_data = queries_data[:limit]

    if verbose:
        print(f"  Loading corpus...")
    with open(CORPUS_PATH) as f:
        corpus = json.load(f)

    if verbose:
        print(f"  Loading BM25 index...")
    bm25_path = BM25_INDEX_DIR + "/lucene"
    bm25_searcher = LuceneSearcher(bm25_path)

    if verbose:
        print(f"  Loading FAISS index...")
    faiss_index = faiss.read_index(FAISS_INDEX_PATH)

    if verbose:
        print(f"  Loading BGE model...")
    dense_model = SentenceTransformer(MODEL_BGE, device="cuda:0")

    if verbose:
        print(f"  Running retrieval for {len(queries_data)} items...")
    results = run_step4(queries_data, corpus, bm25_searcher, dense_model,
                       faiss_index, TOP_K, RRF_K, verbose=verbose)

    with open(RETRIEVAL_PATH, 'w') as f:
        json.dump(results, f, indent=2)
    if verbose:
        total_pairs = sum(len(r["retrieval_pairs"]) for r in results)
        print(f"  Done. {total_pairs} retrieval pairs saved to {RETRIEVAL_PATH}")

    del dense_model
    torch.cuda.empty_cache()
    return results


if __name__ == "__main__":
    main()
